const data = $input.first().json.body || $input.first().json;

if (data.status !== 'completed') {
  return [{ json: { skip: true, reason: `Job status is ${data.status}` } }];
}

let audioUrl = '';
if (data.gcs_uri && data.gcs_uri.startsWith('gs://')) {
    const parts = data.gcs_uri.replace('gs://', '').split('/');
    const bucket = parts.shift();
    const objectPath = parts.join('/');
    audioUrl = `https://storage.googleapis.com/${bucket}/${objectPath}`;
} else {
    return [{ json: { skip: true, reason: 'No valid GCS URI' } }];
}

// Try new format first (site-pid-postId-slug)
let postId = '';
let siteSlug = '';

if (data.job_id.includes('-pid-')) {
    const parts = data.job_id.split('-pid-');
    siteSlug = parts[0];
    postId = parts[1].split('-')[0];
} else {
    // Fallback to old format (search for 24-char hex)
    const parts = data.job_id.split('-');
    const postIdIndex = parts.findIndex(part => part.length === 24 && /^[0-9a-fA-F]+$/.test(part));
    if (postIdIndex !== -1) {
        postId = parts[postIdIndex];
        siteSlug = parts.slice(0, postIdIndex).join('-');
    }
}

if (!postId || postId.length !== 24) {
    return [{ json: { skip: true, reason: `Could not extract valid post ID from: ${data.job_id}` } }];
}

return [{
  json: {
    skip: false,
    jobId: data.job_id,
    postId,
    siteSlug,
    audioUrl,
    gcsUri: data.gcs_uri
  }
}];

const siteSlug = $json.siteSlug;
const isSite1 = siteSlug.includes('founderreality');

// Try environment variables first, then n8n variables
const apiKey1 = $env.GHOST_SITE1_ADMIN_API_KEY || $vars.GHOST_SITE1_ADMIN_API_KEY;
const apiKey2 = $env.GHOST_SITE2_ADMIN_API_KEY || $vars.GHOST_SITE2_ADMIN_API_KEY;

const adminApiKey = isSite1 ? apiKey1 : apiKey2;

if (!adminApiKey || !adminApiKey.includes(':')) {
  throw new Error('Admin API key missing or invalid format (expected key_id:secret). Check n8n Variables or .env.');
}

const [keyId, secret] = adminApiKey.split(':');

// Determine Ghost URL dynamically from env if available, fallback to hardcoded
const ghostUrl = isSite1
  ? ($env.GHOST_SITE1_URL || 'https://ghost.founderreality.com')
  : ($env.GHOST_SITE2_URL || 'https://ghost.getsimpledirect.com');

return [{
  json: {
    ...$json,
    ghostKeyId: keyId,
    ghostSecret: secret,
    ghostUrl: ghostUrl
  }
}];

const postData = $input.first().json;
const post = postData.posts?.[0];

if (!post) {
    throw new Error('Ghost API did not return a post');
}

// Ensure post is still published (Edge case: user unpublished while TTS was running)
if (post.status !== 'published') {
    return [{ json: { skipUpdate: true, reason: `Post is in ${post.status} status, skipping embed` } }];
}

const parsed = $('Check Status & Parse Job ID').first().json;
let html = post.html || '';

if (html.includes('id="gn-audio-embed"')) {
    return [{ json: { skipUpdate: true, reason: 'Audio already embedded' } }];
}

const audioWidget = `
<div id="gn-audio-embed" style="margin-bottom: 24px; padding: 16px; background-color: #f8f9fa; border-radius: 8px; border: 1px solid #e9ecef;">
    <p style="margin-top: 0; margin-bottom: 8px; font-weight: 600; font-size: 0.9em; color: #495057;">&#127911; Listen to this article (AI Narrated)</p>
    <audio controls style="width: 100%; height: 40px;">
        <source src="${parsed.audioUrl}" type="audio/mpeg">
        Your browser does not support the audio element.
    </audio>
</div>
`;

const newHtml = audioWidget + html;

return [{
  json: {
    skipUpdate: false,
    postId: post.id,
    updatedAt: post.updated_at,
    siteSlug: parsed.siteSlug,
    ghostUrl: $json.ghostUrl,
    ghostJwtToken: $json.ghostJwtToken,
    newHtml
  }
}];

const crypto = require('crypto');

const keyId = $json.ghostKeyId;
const secret = $json.ghostSecret;
const now = Math.floor(Date.now() / 1000);

// Ghost Admin API JWT Headers
const header = {
    alg: 'HS256',
    kid: keyId,
    typ: 'JWT'
};

// Ghost Admin API JWT Payload
const payload = {
    iat: now,
    exp: now + 300, // 5 minutes max
    aud: '/admin/'
};

// Helper: Base64URL encode without padding
function base64Url(str) {
    return Buffer.from(str)
        .toString('base64')
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=/g, '');
}

const encodedHeader = base64Url(JSON.stringify(header));
const encodedPayload = base64Url(JSON.stringify(payload));
const signingInput = `${encodedHeader}.${encodedPayload}`;

// CRITICAL: Decode the hex secret into bytes before signing
const keyBytes = Buffer.from(secret, 'hex');

// Sign with HMAC-SHA256
const signature = crypto
    .createHmac('sha256', keyBytes)
    .update(signingInput)
    .digest('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');

const token = `${signingInput}.${signature}`;

return [{
    json: {
        ...$json,
        ghostJwtToken: token
    }
}];
